-- MANUAL TEST SETUP ONLY; never part of automatic migrations. Preserves existing user records.
BEGIN;
DO $sample_run$
DECLARE actor uuid; org uuid; run text := 'TEST-LIFECYCLE-20261025-001'; result jsonb; scenario jsonb; item jsonb; prj uuid; dept uuid; owner uuid; new_id uuid; member_count integer;
BEGIN
 SELECT m.user_id,m.organization_id INTO actor,org FROM public.organization_members m JOIN public.organizations o ON o.id=m.organization_id
 WHERE m.active AND m.role='admin' AND o.name='TEST ONLY · SSM-new1 synthetic workspace';
 IF actor IS NULL THEN RAISE EXCEPTION 'DEDICATED_TEST_ADMIN_REQUIRED'; END IF;
 PERFORM set_config('request.jwt.claim.sub',actor::text,true);
 SELECT count(*) INTO member_count FROM public.organization_members WHERE organization_id=org;
 result:=public.sync_scenario_test_fixtures(run);
 FOR scenario IN SELECT value FROM jsonb_array_elements($scenario_data$[{"id": "S01", "remark": "Harness pin mapping reviewed; fixture cover clearance remains open. Complete fit check before jig validation.", "next": "Mechanical fixture clearance awaiting review by MECH lead.", "history": [{"stageId": "STG-1", "stageName": "Internal Shopfloor Need Identification", "status": "Completed", "startDate": "2026-09-01", "endDate": "2026-09-08", "prerequisite": "Production test bench bottleneck observed on Line 2", "stageRemark": "Shopfloor yield report highlighted 12m manual test overhead per harness.", "decisionOrReason": "Approved by Operations Lead for internal jig development.", "nextAction": "Define scoped technical requirements and pin mapping."}, {"stageId": "STG-2", "stageName": "Requirements & Feasibility", "status": "Completed", "startDate": "2026-09-10", "endDate": "2026-09-20", "prerequisite": "Jig electrical pinout specification drafted", "stageRemark": "Hardware and Mechanical confirmed feasibility with standard 20-pin Pogo block.", "decisionOrReason": "Feasibility sign-off completed by EHW & MECH.", "nextAction": "Produce 3D CAD enclosure and wiring schematic."}, {"stageId": "STG-3", "stageName": "Interface & Fixture Design", "status": "In_Progress", "startDate": "2026-09-25", "prerequisite": "Mechanical clearance fit check with Pogo block", "stageRemark": "Harness pin mapping reviewed; fixture cover clearance remains open. Complete fit check before jig validation.", "decisionOrReason": "Mechanical clearance fit check pending dimensional tolerance review.", "nextAction": "MECH lead review of STL 3D clearance model."}], "tasks": [{"dept": "MECH", "title": "Review fixture cover clearance", "priority": "High", "days": 1, "key": "S01-TASK-01"}, {"dept": "FW", "title": "Prepare EOL flashing script review", "priority": "Normal", "days": 3, "key": "S01-TASK-02"}, {"dept": "EHW", "title": "Confirm harness pin mapping evidence", "priority": "Normal", "days": 2, "key": "S01-TASK-03"}]}, {"id": "S02", "remark": "Requested delivery window cannot accommodate the required qualification work; no confirmed alternate scope accepted.", "next": "Terminal state reached. Archived in Sales Enquiry Register with formal declination letter sent.", "history": [{"stageId": "ENQ-STG-1", "stageName": "Commercial Enquiry Intake", "status": "Completed", "startDate": "2026-09-15", "endDate": "2026-09-18", "prerequisite": "Customer RFQ received via sales portal", "stageRemark": "Customer requested 5,000 units with -40°C operating window in 6 weeks.", "decisionOrReason": "Enquiry qualified and routed for HOD feasibility review.", "nextAction": "Perform multidisciplinary feasibility check."}, {"stageId": "ENQ-STG-2", "stageName": "Multidisciplinary Feasibility Evaluation", "status": "Completed", "startDate": "2026-09-19", "endDate": "2026-09-24", "prerequisite": "Temperature test data on LiFePO4 chemistry and Arrow MCU lead times", "stageRemark": "Arrow component lead-time for automotive -40°C MCU is 14 weeks. Battery heater required.", "decisionOrReason": "Feasibility returned as CONDITIONAL / NOT FEASIBLE within customer schedule.", "nextAction": "Present alternate 16-week timeline to customer."}, {"stageId": "ENQ-STG-3", "stageName": "Commercial Closure & Declination", "status": "Declined", "startDate": "2026-09-26", "endDate": "2026-09-28", "prerequisite": "Customer feedback on alternate schedule", "stageRemark": "Requested delivery window cannot accommodate the required qualification work; no confirmed alternate scope accepted.", "decisionOrReason": "Terminal business declination signed by Sales Lead (Priya Sharma). Zero dummy project created.", "nextAction": "Enquiry record locked in CRM archive."}], "tasks": []}, {"id": "S03", "remark": "Basic reporting demonstrated on the agreed test setup; ignition-state debounce feedback remains pending. PoC acceptance does not authorize mass production.", "next": "Await client PoC feedback and one interface clarification regarding ignition debounce threshold.", "history": [{"stageId": "POC-STG-1", "stageName": "Enquiry & Contract Review Gate", "status": "Completed", "startDate": "2026-08-01", "endDate": "2026-08-10", "prerequisite": "Customer SOR and pilot scope agreed", "stageRemark": "Contract review HLPL/F/MKT/01 approved for 10-unit PoC.", "decisionOrReason": "Project TEST-POC-01 authorized by MD & Sales Lead.", "nextAction": "Draft PRS and tentative BOM."}, {"stageId": "POC-STG-2", "stageName": "PRS & Prototype Bring-up", "status": "Completed", "startDate": "2026-08-12", "endDate": "2026-09-05", "prerequisite": "Reviewed schematic and 10 hand-assembled proto units", "stageRemark": "10 proto units built in Lab 1. CAN telemetry operational.", "decisionOrReason": "Bench test report accepted by QA.", "nextAction": "Deploy to client test vehicle fleet for field validation."}, {"stageId": "POC-STG-3", "stageName": "PoC Field Trial Evaluation", "status": "In_Progress", "startDate": "2026-09-10", "prerequisite": "Customer trial observation period", "stageRemark": "Basic reporting demonstrated on the agreed test setup; ignition-state debounce feedback remains pending. PoC acceptance does not authorize mass production.", "decisionOrReason": "Customer feedback collection active.", "nextAction": "Review ignition line debounce response from Tata engineers."}], "tasks": [{"dept": "SAL", "title": "Obtain client PoC evaluation feedback", "priority": "High", "days": 2, "key": "S03-TASK-01"}, {"dept": "QA", "title": "Review ignition-state debounce test evidence", "priority": "High", "days": 1, "key": "S03-TASK-02"}, {"dept": "PUR", "title": "Confirm prototype component availability", "priority": "Normal", "days": 3, "key": "S03-TASK-03"}]}, {"id": "S04", "remark": "Bench integration complete for the agreed sample configuration; customer pilot observation period remains open.", "next": "Complete 30-day customer pilot observation period across 5 trial commercial trucks.", "history": [{"stageId": "PLT-STG-1", "stageName": "Design Baselines & HSI Freeze", "status": "Completed", "startDate": "2026-07-01", "endDate": "2026-08-15", "prerequisite": "Hardware Schematics Rev B + J1939 Telemetry Spec approved", "stageRemark": "All 5 technical HODs signed off HSI interface baseline.", "decisionOrReason": "Approved for SMT pilot staging.", "nextAction": "Fabricate 50 pilot units on SMT Line 2."}, {"stageId": "PLT-STG-2", "stageName": "Bench Integration & DVP&R Pre-compliance", "status": "Completed", "startDate": "2026-08-20", "endDate": "2026-09-30", "prerequisite": "ISO 7637-2 electrical transient test pass", "stageRemark": "Passed 16 of 18 DVP&R items; temperature chambers certified.", "decisionOrReason": "Pilot release candidate accepted by QA.", "nextAction": "Begin vehicle installation and telemetry observation."}, {"stageId": "PLT-STG-3", "stageName": "Customer Fleet Pilot Trial", "status": "In_Progress", "startDate": "2026-10-01", "prerequisite": "30-day live CAN logging without gateway reboot", "stageRemark": "Bench integration complete for the agreed sample configuration; customer pilot observation period remains open.", "decisionOrReason": "Active customer field observation in Hosur test track.", "nextAction": "Daily OTA telemetry error rate monitoring."}], "tasks": [{"dept": "FW", "title": "Confirm pilot firmware configuration baseline", "priority": "High", "days": 1, "key": "S04-TASK-01"}, {"dept": "SW", "title": "Verify pilot ingestion acknowledgments", "priority": "High", "days": 2, "key": "S04-TASK-02"}, {"dept": "SIT", "title": "Review pilot connection diagnostics", "priority": "Normal", "days": 3, "key": "S04-TASK-03"}, {"dept": "QA", "title": "Review customer pilot observation coverage", "priority": "Normal", "days": 5, "key": "S04-TASK-04"}]}, {"id": "S05", "remark": "Pilot feedback identified intermittent alert duplication; corrective candidate is under regression review. Final customer acceptance and bulk release remain blocked.", "next": "QA regression re-test of firmware patch v2.1.2 on cell handover test bench.", "history": [{"stageId": "REF-STG-1", "stageName": "Engineering & Pilot Build", "status": "Completed", "startDate": "2026-06-01", "endDate": "2026-08-30", "prerequisite": "All engineering CAD, schematics, and pilot batch verified", "stageRemark": "Initial pilot hardware build delivered to customer fleet.", "decisionOrReason": "Historical engineering phase completed.", "nextAction": "Customer pilot observation."}, {"stageId": "REF-STG-2", "stageName": "Pilot Observation & Issue Logging", "status": "Completed", "startDate": "2026-09-01", "endDate": "2026-09-20", "prerequisite": "Customer anomaly report logged in NCR system", "stageRemark": "Customer reported duplicate high-temperature excursion SMS alerts.", "decisionOrReason": "ECR-2026-042 raised by QA for cellular queue debounce.", "nextAction": "Firmware team patch and regression verification."}, {"stageId": "REF-STG-3", "stageName": "Regression Verification & Refinement", "status": "Under_Review", "startDate": "2026-09-25", "prerequisite": "Zero alert duplication on cell border simulated handover", "stageRemark": "Pilot feedback identified intermittent alert duplication; corrective candidate is under regression review. Final customer acceptance and bulk release remain blocked.", "decisionOrReason": "Patch v2.1.2 under dual testing by FW and QA.", "nextAction": "Complete 48-hour continuous cellular tower roaming loop test."}], "tasks": [{"dept": "FW", "title": "Regression-test alert duplication correction", "priority": "Critical", "days": -1, "key": "S05-TASK-01"}, {"dept": "QA", "title": "Review refinement regression results", "priority": "High", "days": 2, "key": "S05-TASK-02"}, {"dept": "SAL", "title": "Confirm customer refinement acceptance criteria", "priority": "Normal", "days": 4, "key": "S05-TASK-03"}]}, {"id": "S06", "remark": "Hold disposition pending for five units; only accepted quantity is eligible for release.", "next": "QA material review board disposition on 5 held units; release 150 accepted units to dispatch.", "history": [{"stageId": "PRD-STG-1", "stageName": "APQP & Production Readiness Release", "status": "Completed", "startDate": "2026-05-01", "endDate": "2026-07-31", "prerequisite": "PPAP Level 3, Control Plan, and Line 1 Qualification", "stageRemark": "PPAP warrant signed by client. SMT reflow profile validated.", "decisionOrReason": "Formal mass production release authorized by MD.", "nextAction": "Issue Work Order for Lot 1 (200 units)."}, {"stageId": "PRD-STG-2", "stageName": "Lot 1 Production Run & EOL Testing", "status": "In_Progress", "startDate": "2026-08-01", "prerequisite": "Automated test jig flashing and AOI inspection", "stageRemark": "Hold disposition pending for five units; only accepted quantity is eligible for release.", "decisionOrReason": "150 units passed 100% EOL (accepted); 5 units held pending MRB disposition; 45 units pending final inspection.", "nextAction": "Execute MRB disposition and ship first 150 units with commercial invoice."}], "tasks": [{"dept": "EMF", "title": "Review first-lot manufacturing records", "priority": "High", "days": 1, "key": "S06-TASK-01"}, {"dept": "QA", "title": "Review disposition of five held units", "priority": "Critical", "days": 1, "key": "S06-TASK-02"}, {"dept": "PUR", "title": "Review material readiness for remaining planned units", "priority": "Normal", "days": 4, "key": "S06-TASK-03"}, {"dept": "FIN", "title": "Review production cost source reconciliation", "priority": "Normal", "days": 5, "key": "S06-TASK-04"}]}]$scenario_data$::jsonb) LOOP
   SELECT canonical_id INTO prj FROM public.scenario_fixture_manifests WHERE organization_id=org AND run_id=run AND scenario_id=scenario->>'id' AND entity_type='project';
   UPDATE public.operational_records r SET fields=r.fields || jsonb_build_object('fixtureRunId',run,'sampleScenario',scenario->>'id','simulated',true,'stageRemark',scenario->>'remark','nextAction',scenario->>'next','stageHistory',(scenario->'history')::text),
     notes=concat_ws(E'\n',NULLIF(r.notes,''),'TEST ONLY — synthetic lifecycle history; not actual client acceptance or compliance evidence.',scenario->>'remark','Next action: '||(scenario->>'next'))
   WHERE r.organization_id=org AND r.id IN (SELECT canonical_id FROM public.scenario_fixture_manifests WHERE organization_id=org AND run_id=run AND scenario_id=scenario->>'id' AND entity_type IN ('project','record','enquiry'))
     AND r.fields->>'fixtureRunId' IS DISTINCT FROM run;
   FOR item IN SELECT value FROM jsonb_array_elements(scenario->'tasks') LOOP
     IF prj IS NULL THEN RAISE EXCEPTION 'SCENARIO_PROJECT_MISSING'; END IF;
     SELECT id INTO dept FROM public.departments WHERE organization_id=org AND code=item->>'dept' AND active;
     SELECT m.id INTO owner FROM public.organization_members m WHERE m.organization_id=org AND m.active AND m.role='department_lead' AND private.shared_test_member_department(m.id)=dept LIMIT 1;
     IF dept IS NULL OR owner IS NULL THEN RAISE EXCEPTION 'SCENARIO_TASK_OWNER_MISSING: %',item->>'dept'; END IF;
     SELECT (public.mutate_shared_test_workspace('create_task',jsonb_build_object('project_id',prj,'department_id',dept,'title','TEST '||(scenario->>'id')||' · '||(item->>'title'),'priority',item->>'priority','assignee_id',owner,'due_at',(((DATE '2026-10-25'+(item->>'days')::int)+TIME '17:00') AT TIME ZONE 'Asia/Kolkata')),md5(run||':'||(item->>'key'))::uuid)->>'id')::uuid INTO new_id;
     INSERT INTO public.scenario_fixture_manifests(organization_id,run_id,scenario_id,fixture_key,entity_type,record_type,canonical_id,reference,metadata)
     VALUES(org,run,scenario->>'id',item->>'key','task','Task',new_id,item->>'key',jsonb_build_object('simulated',true,'department',item->>'dept')) ON CONFLICT DO NOTHING;
   END LOOP;
 END LOOP;
 IF (SELECT count(*) FROM public.scenario_fixture_manifests WHERE organization_id=org AND run_id=run AND entity_type='project')<>5 THEN RAISE EXCEPTION 'EXPECTED_FIVE_PROJECTS'; END IF;
 IF EXISTS(SELECT 1 FROM public.scenario_fixture_manifests WHERE organization_id=org AND run_id=run AND scenario_id='S02' AND entity_type='project') THEN RAISE EXCEPTION 'DECLINED_ENQUIRY_HAS_PROJECT'; END IF;
 IF (SELECT count(*) FROM public.organization_members WHERE organization_id=org)<>member_count THEN RAISE EXCEPTION 'MEMBERSHIPS_CHANGED'; END IF;
END $sample_run$;
COMMIT;
SELECT scenario_id,entity_type,count(*) AS linked_entries FROM public.scenario_fixture_manifests WHERE run_id='TEST-LIFECYCLE-20261025-001' GROUP BY scenario_id,entity_type ORDER BY scenario_id,entity_type;
